from pysat.solvers import Glucose3
from pysat.card import *

# N-Queens problem with N=14
N = 14

# Fixed assignments
fixed = {4: 4, 6: 1}

# We'll use a SAT solver approach
# Variables: x[r][c] means queen is at row r, column c
# Variable index: r*N + c + 1 (1-indexed for SAT)

def var(r, c):
    return r * N + c + 1

solver = Glucose3()

# Each row must have exactly one queen
for r in range(N):
    # At least one queen in row r
    solver.add_clause([var(r, c) for c in range(N)])
    # At most one queen in row r
    for c1 in range(N):
        for c2 in range(c1+1, N):
            solver.add_clause([-var(r, c1), -var(r, c2)])

# Each column must have at most one queen
for c in range(N):
    for r1 in range(N):
        for r2 in range(r1+1, N):
            solver.add_clause([-var(r1, c), -var(r2, c)])

# No two queens on the same diagonal
# Main diagonals (r - c = constant)
for r1 in range(N):
    for c1 in range(N):
        for r2 in range(r1+1, N):
            for c2 in range(N):
                if r1 - c1 == r2 - c2:  # same main diagonal
                    solver.add_clause([-var(r1, c1), -var(r2, c2)])
                if r1 + c1 == r2 + c2:  # same anti-diagonal
                    solver.add_clause([-var(r1, c1), -var(r2, c2)])

# Fixed assignments
for r, c in fixed.items():
    solver.add_clause([var(r, c)])
    # No other queen in this row
    for c2 in range(N):
        if c2 != c:
            solver.add_clause([-var(r, c2)])
    # No other queen in this column
    for r2 in range(N):
        if r2 != r:
            solver.add_clause([-var(r2, c)])

if solver.solve():
    model = solver.get_model()
    solution = []
    for r in range(N):
        for c in range(N):
            if var(r, c) in model:
                solution.append(c)
                break
    print("Solution found:", solution)
    # Verify
    for i in range(N):
        for j in range(i+1, N):
            assert solution[i] != solution[j], f"Column conflict: rows {i},{j}"
            assert abs(solution[i] - solution[j]) != abs(i - j), f"Diagonal conflict: rows {i},{j}"
    print("Solution verified!")
else:
    print("UNSATISFIABLE")

solver.delete()
